long long strongestCrew(int* strength, int strengthSize) {
    long long best = 0;
    for (int i = 0; i < strengthSize; i++) {
        int low = strength[i];
        long long total = 0;
        for (int j = i; j < strengthSize; j++) {
            if (strength[j] < low) low = strength[j];
            total += strength[j];
            if (low * total > best) best = low * total;
        }
    }
    return best;
}

