class Solution:
    def strongestCrew(self, strength: List[int]) -> int:
        n = len(strength)
        P = [0] * (n + 1)
        for i, v in enumerate(strength):
            P[i + 1] = P[i] + v
        left, stack = [0] * n, []
        for i in range(n):
            while stack and strength[stack[-1]] >= strength[i]:
                stack.pop()
            left[i] = stack[-1] + 1 if stack else 0
            stack.append(i)
        best, stack = 0, []
        for i in range(n - 1, -1, -1):
            while stack and strength[stack[-1]] >= strength[i]:
                stack.pop()
            right = stack[-1] - 1 if stack else n - 1
            best = max(best, strength[i] * (P[right + 1] - P[left[i]]))
            stack.append(i)
        return best

