class Solution {
    public long strongestCrew(int[] strength) {
        int n = strength.length;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + strength[i];
        int[] left = new int[n], stack = new int[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            while (top > 0 && strength[stack[top - 1]] >= strength[i]) top--;
            left[i] = top > 0 ? stack[top - 1] + 1 : 0;
            stack[top++] = i;
        }
        long best = 0;
        top = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (top > 0 && strength[stack[top - 1]] >= strength[i]) top--;
            int right = top > 0 ? stack[top - 1] - 1 : n - 1;
            best = Math.max(best, strength[i] * (P[right + 1] - P[left[i]]));
            stack[top++] = i;
        }
        return best;
    }
}

