class Solution {
public:
    long long strongestCrew(vector<int>& strength) {
        int n = strength.size();
        vector<long long> P(n + 1, 0);
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + strength[i];
        vector<int> left(n), stack;
        for (int i = 0; i < n; i++) {
            while (!stack.empty() && strength[stack.back()] >= strength[i]) stack.pop_back();
            left[i] = stack.empty() ? 0 : stack.back() + 1;
            stack.push_back(i);
        }
        long long best = 0;
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.empty() && strength[stack.back()] >= strength[i]) stack.pop_back();
            int right = stack.empty() ? n - 1 : stack.back() - 1;
            best = max(best, strength[i] * (P[right + 1] - P[left[i]]));
            stack.push_back(i);
        }
        return best;
    }
};

