long long strongestCrew(int* strength, int strengthSize) {
    int n = strengthSize;
    long long* P = malloc((n + 1) * sizeof(long long));
    P[0] = 0;
    for (int i = 0; i < n; i++) P[i + 1] = P[i] + strength[i];
    int* left = malloc(n * sizeof(int));
    int* stack = malloc(n * sizeof(int));
    int top = 0;
    for (int i = 0; i < n; i++) {
        while (top > 0 && strength[stack[top - 1]] >= strength[i]) top--;
        left[i] = top > 0 ? stack[top - 1] + 1 : 0;
        stack[top++] = i;
    }
    long long best = 0;
    top = 0;
    for (int i = n - 1; i >= 0; i--) {
        while (top > 0 && strength[stack[top - 1]] >= strength[i]) top--;
        int right = top > 0 ? stack[top - 1] - 1 : n - 1;
        long long power = strength[i] * (P[right + 1] - P[left[i]]);
        if (power > best) best = power;
        stack[top++] = i;
    }
    free(P);
    free(left);
    free(stack);
    return best;
}
